 navigation();supplyWorkspace();mvpNotice();mapControls();mapPanelLayout();mapIndicatorPicker();exploreWorkspace();mapFocus();simpleLocationLayer();mapNavigation();technical();sourceTables();unifiedSources();ranking();simpleRanking();sheet();modalHelp();categories();selectedLabels();informationDesign();rankingIntensity();simplifyNumbers();supplyEvidence();cattleFlows();propertyFigure();factorTable();indicatorGuide();overviewTable();municipalityLocator();diagnosisTable();conciseDiagnosis();municipalNavigation();simplerPropertySection();directChainResults();compactMovementRoutes();cattleSankey();consistentResultTables();mapResultReading();propertyAreaAccess();municipalReport();decisionFirst();aboutAtlas();brazilContext();scopeLabels();mainQuestions();
 document.querySelectorAll('.summary-card').forEach(card=>{const dot=card.querySelector('.dot');if(dot)card.style.setProperty('--diagnosis-color',getComputedStyle(dot).backgroundColor);});
 document.querySelectorAll('#chain-access-distances> .wrap>h2').forEach(h=>put(h,t('Distâncias entre locais mapeados','Distances between mapped locations')));
